"""All lab tests, grouped by exercise. Do not edit this file."""
import unittest
from adapters import InMemoryRepository, RecordingChannel
from models import Task, Assignee, SaveError, NotificationError
from service import TaskService
from push_channel import PushChannel
from audit_channel import AuditedChannel

ALICE = Assignee('u1', 'email', 'alice@example.test')
MESSAGE = 'You were assigned: Write report'

def setup_service(*, fail_save=False, fail_send=False):
    trace = []
    repository = InMemoryRepository(
        [Task('t1', 'Write report')], fail_save=fail_save, trace=trace)
    email = RecordingChannel(fail=fail_send, trace=trace)
    sms = RecordingChannel(trace=trace)
    service = TaskService(repository, {'email': email, 'sms': sms})
    return service, repository, email, sms, trace

class TestExercise1(unittest.TestCase):
    """SRP and DIP: use injected collaborators and preserve save ordering."""

    def test_assignment_is_saved_and_email_is_sent(self):
        service, repository, email, sms, trace = setup_service()
        task = service.assign_task('t1', ALICE)
        self.assertEqual(task.assignee_id, 'u1')
        self.assertEqual(repository.persisted('t1'), task)
        self.assertEqual(email.sent, [(ALICE.contact, MESSAGE)])
        self.assertEqual(sms.sent, [])

    def test_save_happens_before_send(self):
        service, repository, email, sms, trace = setup_service()
        service.assign_task('t1', ALICE)
        self.assertEqual(trace, ['get', 'save', 'send'])

    def test_save_failure_propagates_without_any_send_attempt(self):
        service, repository, email, sms, trace = setup_service(fail_save=True)
        with self.assertRaises(SaveError):
            service.assign_task('t1', ALICE)
        self.assertEqual(email.attempts, 0)
        self.assertEqual(sms.attempts, 0)
        self.assertIsNone(repository.persisted('t1').assignee_id)

class TestExercise2(unittest.TestCase):
    """Strategy and OCP: select interchangeable channels by registration."""

    def test_sms_is_selected_from_the_assignee_preference(self):
        service, repository, email, sms, trace = setup_service()
        bob = Assignee('u2', 'sms', '+10000000000')
        service.assign_task('t1', bob)
        self.assertEqual(sms.sent, [(bob.contact, MESSAGE)])
        self.assertEqual(email.attempts, 0)

    def test_push_channel_records_each_request(self):
        push = PushChannel()
        push.send('device-1', 'first')
        push.send('device-2', 'second')
        self.assertEqual(push.sent,
                         [('device-1', 'first'), ('device-2', 'second')])

    def test_push_works_through_the_same_task_service(self):
        repository = InMemoryRepository([Task('t1', 'Write report')])
        push = PushChannel()
        service = TaskService(repository, {'push': push})
        task = service.assign_task('t1', Assignee('u3', 'push', 'device-3'))
        self.assertEqual(push.sent, [('device-3', MESSAGE)])
        self.assertEqual(repository.persisted('t1'), task)

class TestExercise3(unittest.TestCase):
    """Failure boundaries: keep saved state, do not retry or hide bugs."""

    def test_notification_failure_keeps_assignment_and_attempts_once(self):
        service, repository, email, sms, trace = setup_service(fail_send=True)
        task = service.assign_task('t1', ALICE)
        self.assertEqual(task.assignee_id, 'u1')
        self.assertEqual(repository.persisted('t1'), task)
        self.assertEqual(email.attempts, 1)
        self.assertEqual(email.sent, [])
        self.assertEqual(trace, ['get', 'save', 'send'])

    def test_expected_notification_failure_logs_a_warning(self):
        service, repository, email, sms, trace = setup_service(fail_send=True)
        with self.assertLogs('service', level='WARNING') as captured:
            service.assign_task('t1', ALICE)
        self.assertTrue(captured.output)
        self.assertNotIn(ALICE.contact, '\n'.join(captured.output))

    def test_unexpected_provider_bug_remains_visible_after_save(self):
        class BrokenChannel:
            def send(self, recipient, message):
                raise RuntimeError('unexpected provider bug')

        repository = InMemoryRepository([Task('t1', 'Write report')])
        service = TaskService(repository, {'email': BrokenChannel()})
        with self.assertRaises(RuntimeError):
            service.assign_task('t1', ALICE)
        self.assertEqual(repository.persisted('t1').assignee_id, ALICE.id)

class TestExercise4(unittest.TestCase):
    """Decorator: add an acceptance record while preserving the channel contract."""

    def test_delegates_once_and_records_each_accepted_request(self):
        inner = RecordingChannel()
        audited = AuditedChannel(inner)
        audited.send('device-1', 'first')
        audited.send('device-2', 'second')
        self.assertEqual(inner.sent,
                         [('device-1', 'first'), ('device-2', 'second')])
        self.assertEqual(inner.attempts, 2)
        self.assertEqual(audited.events,
                         ['notification.accepted', 'notification.accepted'])

    def test_delegate_failure_propagates_without_an_acceptance_record(self):
        inner = RecordingChannel(fail=True)
        audited = AuditedChannel(inner)
        with self.assertRaises(NotificationError):
            audited.send('device-1', 'first')
        self.assertEqual(inner.attempts, 1)
        self.assertEqual(audited.events, [])

    def test_decorator_is_injected_without_changing_task_service(self):
        repository = InMemoryRepository([Task('t1', 'Write report')])
        push = PushChannel()
        audited = AuditedChannel(push)
        service = TaskService(repository, {'push': audited})
        task = service.assign_task('t1', Assignee('u3', 'push', 'device-3'))
        self.assertEqual(repository.persisted('t1'), task)
        self.assertEqual(push.sent, [('device-3', MESSAGE)])
        self.assertEqual(audited.events, ['notification.accepted'])


def main():
    """Run one exercise or all checks with an explicit pass/fail exit code."""
    import argparse

    parser = argparse.ArgumentParser(description='Task assignment lab checks')
    parser.add_argument('exercise', choices=('1', '2', '3', '4', 'all'),
                        default='all', nargs='?', help='exercise number or all')
    selected = parser.parse_args().exercise
    groups = {'1': TestExercise1, '2': TestExercise2,
              '3': TestExercise3, '4': TestExercise4}
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()
    for key in (groups if selected == 'all' else [selected]):
        suite.addTests(loader.loadTestsFromTestCase(groups[key]))
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    return 0 if result.wasSuccessful() else 1


if __name__ == '__main__':
    raise SystemExit(main())
